def _load_chat_files_content(
    self,
    chat_files: List[str],
    already_in_messages: Set[str]
) -> str:
    """
    Read and format the content of files explicitly attached to the chat.

    Files already embedded as code blocks in the message history are skipped
    to avoid duplication.

    CHANGED: Binary files (PDFs, images) are now detected and skipped
    from the text content accumulator. They are instead returned as
    separate binary file metadata so they can be passed to the LLM
    via the vision API if supported by the model.

    :param chat_files: List of file paths to load.
    :param already_in_messages: Set of file paths already present in message bodies.
    :return: Tuple of (text_content_string, binary_files_list).
    """
    chat_files_content = ""
    binary_files = []

    for chat_file in chat_files:
        if chat_file in already_in_messages:
            continue

        chat_file_full_path = self._resolve_chat_file_path(chat_file)
        if not chat_file_full_path:
            continue

        try:
            # Check if binary BEFORE attempting to read as text
            if self.session.file_engine._is_binary_file(chat_file_full_path):
                logger.info(
                    "Binary file detected (will pass to LLM separately): '%s'",
                    chat_file_full_path
                )
                binary_files.append({
                    "path": chat_file,
                    "full_path": chat_file_full_path
                })
                continue

            with open(chat_file_full_path, "r", encoding="utf-8") as fh:
                source = chat_file_full_path.replace(
                    self.settings.abs_project_path + "/", ""
                )
                logger.info(
                    "Loading chat_file content from '%s' with source: '%s'",
                    chat_file_full_path,
                    source
                )
                doc_context = self._document_to_context(
                    Document(
                        page_content=fh.read(),
                        metadata={"source": source}
                    )
                )
                chat_files_content += doc_context + "\n"
        except UnicodeDecodeError:
            logger.warning(
                "Failed to decode '%s' as UTF-8; treating as binary",
                chat_file_full_path
            )
            binary_files.append({
                "path": chat_file,
                "full_path": chat_file_full_path
            })
        except OSError as ex:
            logger.error("Error adding context file to chat: %s", ex)

    return chat_files_content, binary_files

@staticmethod
def _prepare_vision_content(
    binary_files: List[Dict[str, str]],
    binary_attachments: List[Dict[str, Any]]
) -> List[Dict[str, Any]]:
    """
    Convert binary files and attachments to OpenAI vision API format.

    Supports both file paths and inline base64 data URIs.
    Infers MIME type from file extension.

    Format returned matches OpenAI Chat Completions API vision support:
    https://platform.openai.com/docs/guides/vision

    :param binary_files: List of {'path', 'full_path'} dicts from chat files.
    :param binary_attachments: List of {'source_message_id', 'attachment'} from messages.
    :return: List of content blocks (text, image_url, or file types).
    """
    vision_content = []

    # Process binary chat files
    for binary_file in binary_files:
        full_path = binary_file["full_path"]
        mime_type = ChatEngine._get_mime_type_for_file(full_path)

        try:
            with open(full_path, "rb") as f:
                file_bytes = f.read()
            base64_data = base64.b64encode(file_bytes).decode("utf-8")

            # Format as data URI (supported by most vision models)
            data_uri = f"data:{mime_type};base64,{base64_data}"

            if mime_type.startswith("image/"):
                vision_content.append({
                    "type": "image_url",
                    "image_url": {"url": data_uri}
                })
            elif mime_type == "application/pdf":
                # GPT-4o supports PDF via file type
                vision_content.append({
                    "type": "file",
                    "file": {
                        "filename": os.path.basename(full_path),
                        "file_data": data_uri
                    }
                })
            else:
                logger.debug(
                    "Skipping binary file (unsupported MIME type): %s -> %s",
                    full_path, mime_type
                )
        except OSError as ex:
            logger.warning("Failed to read binary file %s: %s", full_path, ex)

    # Process message attachments (already base64 encoded)
    for attachment_info in binary_attachments:
        attachment = attachment_info["attachment"]
        try:
            # Assume attachment is already a data URI or base64 string
            if attachment.startswith("data:"):
                if "image/" in attachment:
                    vision_content.append({
                        "type": "image_url",
                        "image_url": {"url": attachment}
                    })
                # Could extend for other types
        except Exception as ex:
            logger.debug("Failed to process attachment: %s", ex)

    return vision_content

@staticmethod
def _get_mime_type_for_file(file_path: str) -> str:
    """
    Determine MIME type from file extension.

    :param file_path: File path.
    :return: MIME type string.
    """
    _, ext = os.path.splitext(file_path)
    ext = ext.lstrip(".").lower()

    mime_map = {
        "pdf": "application/pdf",
        "png": "image/png",
        "jpg": "image/jpeg",
        "jpeg": "image/jpeg",
        "gif": "image/gif",
        "webp": "image/webp",
    }

    return mime_map.get(ext, "application/octet-stream")

@staticmethod
def convert_message(message: Message):
    """
    Convert a DB Message object into a LangChain message type.

    Handles text-only messages, image messages, and role-based conversion.

    :param message: The Message object to convert.
    :return: A LangChain HumanMessage, AIMessage, or image dict.
    """
    def parse_image(image) -> dict:
        """
        Parse an image into a dict with src and alt fields.

        Handles both ChatAttachment objects and legacy JSON strings.
        """
        # Handle ChatAttachment objects (new format)
        if isinstance(image, ChatAttachment):
            return {
                "src": f"data:{image.file_type};base64,{image.base64_data}",
                "alt": image.file_name
            }

        # Handle legacy JSON string format
        if isinstance(image, str):
            try:
                return json.loads(image)
            except (json.JSONDecodeError, TypeError):
                return {"src": image, "alt": ""}

        # Fallback for other types
        return {"src": str(image), "alt": ""}

    if message.attachments:
        images = [parse_image(image) for image in message.attachments]
        text_content = {
            "type": "text",
            "text": message.content
        }
        content = [text_content] + [
            {
                "type": "image_url",
                "image_url": {"url": image["src"]}
            }
            for image in images
        ]
        msg = {"type": "image", "content": json.dumps(content)}
    elif message.role == "user":
        msg = HumanMessage(content=message.content)
    else:
        msg = AIMessage(content=message.content)

    return msg

